args.code:
T0 = None
PH = 'fwd'

def control(obs):
    global T0, PH
    t = obs['t']
    h = obs['hitch_deg']
    st = obs['status']
    if T0 is None:
        T0 = t
    if PH == 'rev' and (st in ('JACKKNIFED', 'PINNED') or abs(h) > 40):
        PH = 'fwd'
        T0 = t
    if PH == 'fwd':
        if t - T0 < 2.5:
            return (8.0, 0.6, 180)
        PH = 'rev'
        T0 = t
    steer = max(-30.0, min(30.0, 1.2 * (h - 2.0)))
    return (steer, -0.6, 180)

