T1 = None
T2 = None

def control(obs):
    global PH, T1, T2
    t = obs['t']
    v = obs['motion']['v_mps']
    h = obs['hitch_deg']
    if PH == 0:
        if v > 0.05:
            if T1 is None:
                T1 = t
            if t - T1 >= 3.0:
                PH = 1
        return (12.0, 0.6, -41)
    if PH == 1:
        if abs(v) < 0.02:
            PH = 2
            T2 = None
        return (0.0, 0.0, -41)
    if PH == 2:
        if v < -0.1:
            if T2 is None:
                T2 = t
            if t - T2 >= 2.0:
                PH = 3
        return (-8.0, -1.0, -41)
    steer = max(-25.0, min(25.0, 1.5 * h))
    return (steer, -1.0, -41)

