def clamp(x, a, b):
    return max(a, min(b, x))

def control(obs):
    global MODE, NEXT
    h = obs['hitch_deg']
    v = obs['motion']['v_mps']
    ry = obs['rig']['trailer_rear'][1]
    st = obs['status']
    if MODE == 'fwd':
        if ry >= 0.95 or h > 6.0:
            MODE = 'brake'
            NEXT = 'rev'
            return (0.0, 0.0, -41)
        return (3.0, 0.3, -41)
    if MODE == 'brake':
        if abs(v) < 0.02:
            MODE = NEXT
        return (0.0, 0.0, -41)
    if st in ('PINNED', 'JACKKNIFED') or ry < 0.4:
        MODE = 'brake'
        NEXT = 'fwd'
        return (0.0, 0.0, -41)
    th = clamp(3.0 * (0.9 - ry), -4.0, 4.0)
    steer = clamp(2.5 * (h - th), -15.0, 15.0)
    return (steer, -0.3, -41)

